import java.io.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int[] freq = new int[26], totals = new int[26];
        for (int k = 0; k < s.length(); k++) {
            freq[s.charAt(k) - 'a']++;
            int top = 0;
            for (int f : freq) top = Math.max(top, f);
            for (int i = 0; i < 26; i++)
                if (freq[i] == top) totals[i]++;
        }
        int answer = 0;
        for (int t : totals) answer = Math.max(answer, t);
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	var freq, totals [26]int
	for _, ch := range next() {
		freq[ch-'a']++
		top := slices.Max(freq[:])
		for i := range freq {
			if freq[i] == top {
				totals[i]++
			}
		}
	}
	os.Stdout.WriteString(strconv.Itoa(slices.Max(totals[:])) + "\n")
}
